function historicalStatsData(){
  const hs = state.historicalStats;
  if(hs && !Array.isArray(hs) && typeof hs === "object" && hs.summary && hs.seasons && hs.allTimeGoals && hs.allTimeAppearances){
    return hs;
  }
  return defaults.historicalStats;
}
function numIt(v){return typeof v === "number" ? v.toLocaleString("it-IT") : (v ?? "");}
function statDiff(v){return Number(v)>0?`+${v}`:`${v}`;}
function seasonStatsRows(rows){return (rows||[]).map(s=>`<tr><td>${s.season}</td><td>${numIt(s.played)}</td><td>${numIt(s.wins)}</td><td>${numIt(s.draws)}</td><td>${numIt(s.losses)}</td><td>${numIt(s.goalsFor)} <span class="muted">(${s.goalsForAvg||""})</span></td><td>${numIt(s.goalsAgainst)} <span class="muted">(${s.goalsAgainstAvg||""})</span></td><td>${statDiff(s.goalDifference)}</td></tr>`).join("");}
function rankingRows(rows){return (rows||[]).map((r,i)=>`<tr><td>${i+1}</td><td>${r.players}</td><td>${numIt(r.value)}</td></tr>`).join("");}
function records(){
  const hs = historicalStatsData();
  const s = hs.summary || {};
  const topGoals = (hs.allTimeGoals || [])[0] || {};
  const topApps = (hs.allTimeAppearances || [])[0] || {};
  const cards = [
    {label:"Gare ufficiali", value: toNumber(s.played), detail:`Bilancio storico: ${toNumber(s.wins)} vittorie, ${toNumber(s.draws)} pareggi, ${toNumber(s.losses)} sconfitte`},
    {label:"Vittorie", value: toNumber(s.wins), detail:"Vittorie complessive storiche"},
    {label:"Gol fatti", value: toNumber(s.goalsFor), detail:`Media ${avgPerGame(s.goalsFor,s.played)} gol a partita`},
    bestWinsSeason(hs),
    {label:"Top gol all time", value: topGoals.value || 0, detail: topGoals.players || "Dato non disponibile"},
    {label:"Top presenze all time", value: topApps.value || 0, detail: topApps.players || "Dato non disponibile"}
  ];
  shell("Hall of fame","Record e milestone del club",`
    <div class="grid grid-3">${cards.map(r=>`<div class="record-card"><span class="eyebrow">${r.label}</span><h2 style="font-size:34px">${numIt(r.value)}</h2><p style="color:rgba(255,255,255,.68)">${r.detail}</p></div>`).join("")}</div>
    <div class="newsletter" style="margin-top:28px">
      <span class="eyebrow" style="background:white;color:#09090b">Archivio completo</span>
      <h2 style="font-size:38px">Tutte le statistiche storiche, reti e presenze.</h2>
      <p style="color:rgba(255,255,255,.72)">Apri la pagina completa con riepilogo storico, classifica marcatori, classifica presenze e statistiche stagione per stagione.</p>
      <button class="btn ghost" onclick="route('historical-stats')">Vai alle statistiche complete →</button>
    </div>
  `,"","Record e hall of fame CUS Trento C5.");
}
