  shell("Club","Chi siamo",`<div class="grid grid-2"><article class="card card-pad"><span class="eyebrow">Storia</span><h2 style="font-size:34px;margin-bottom:16px">${esc(historyTitle)}</h2>${renderParagraphs(historyParagraphs)}</article><article class="card card-pad"><span class="eyebrow">Progetto</span><h2 style="font-size:34px;margin-bottom:16px">${esc(projectTitle)}</h2>${renderParagraphs(projectParagraphs)}${projectGallery}</article></div>` ,"","Storia e progetto sportivo del CUS Trento C5.");
