// ===== CMS BOOT: carica i contenuti pubblicati da content/data.json + archivio news importate =====
function newsKeyForMerge(n){
  return String(
    (n && (n.sourceUrl || n._sportrentino_source_url || n.sourceId || n.id)) ||
    `${n && n.title || ""}|${n && n.date || ""}`
  );
}

function sortNewsForFrontend(news){
  return [...(news || [])].sort((a,b)=>{
    const da = String(a && a.date || "");
    const db = String(b && b.date || "");
    if(db !== da) return db.localeCompare(da);
    return Number(b && b.id || 0) - Number(a && a.id || 0);
  });
}

function mergeCmsNewsWithImportedArchive(cmsNews, importedNews){
  const merged = [];
  const seen = new Set();

  // Prima le news del CMS: se una news nuova viene importata in data.json, vince su eventuali copie archiviate.
  (cmsNews || []).forEach(n=>{
    const key = newsKeyForMerge(n);
    if(!seen.has(key)){
      seen.add(key);
      merged.push(n);
    }
  });

  // Poi l'archivio storico read-only, che non deve appesantire il CMS.
  (importedNews || []).forEach(n=>{
    const key = newsKeyForMerge(n);
    if(!seen.has(key)){
      seen.add(key);
      merged.push(n);
    }
  });

  return sortNewsForFrontend(merged);
}

async function loadImportedNewsArchive(){
  try{
    const res = await fetch('/content/news.imported.json', {cache:'no-cache'});
    if(!res.ok){
      console.warn(`content/news.imported.json non caricato: HTTP ${res.status}. Il sito userà solo le news CMS.`);
      return [];
    }

    const raw = await res.text();
    const archive = JSON.parse(raw);
    if(Array.isArray(archive)) return archive;
    if(archive && Array.isArray(archive.news)) return archive.news;
    return [];
  }catch(e){
    console.warn("Errore caricamento content/news.imported.json. Il sito userà solo le news CMS.", e);
    return [];
  }
}

async function loadImportedNewsIndex(){
  try{
    const res = await fetch('/content/news.index.json', {cache:'no-cache'});
    if(!res.ok){
      if(res.status !== 404) console.warn(`content/news.index.json non caricato: HTTP ${res.status}.`);
      return [];
    }
    const raw = await res.text();
    const payload = JSON.parse(raw);
    if(Array.isArray(payload)) return payload;
    if(payload && Array.isArray(payload.news)) return payload.news;
    return [];
  }catch(e){
    console.warn("Errore caricamento content/news.index.json. Il sito userà solo le news CMS fino al caricamento dell'archivio.", e);
    return [];
  }
}

let importedNewsArchivePromise = null;
function upgradeNewsWithFullArchive(existingNews, importedArchiveNews){
  const fullByKey = new Map((importedArchiveNews || []).map(n => [newsKeyForMerge(n), n]));
  const upgraded = (existingNews || []).map(n => {
    const full = fullByKey.get(newsKeyForMerge(n));
    if(full && (full.bodyHtml || (Array.isArray(full.body) && full.body.length))){
      return {...n, ...full};
    }
    return n;
  });
  return mergeCmsNewsWithImportedArchive(upgraded, importedArchiveNews || []);
}
function scheduleImportedNewsArchiveLoad(delayMs){
  if(importedNewsArchivePromise) return importedNewsArchivePromise;
  importedNewsArchivePromise = new Promise(resolve => {
    const run = async function(){
      const importedArchiveNews = await loadImportedNewsArchive();
      if(importedArchiveNews && importedArchiveNews.length){
        state.news = upgradeNewsWithFullArchive(state.news || [], importedArchiveNews);
        if(current === "news" || current.startsWith("article-")) render();
      }
      resolve(importedArchiveNews || []);
    };
    const delay = Number.isFinite(delayMs) ? Math.max(0, delayMs) : 3000;
    setTimeout(run, delay);
  });
  return importedNewsArchivePromise;
}

