async function loadOptionalJson(path){
  try{
    const res = await fetch(path, {cache:'no-cache'});
    if(!res.ok){
      if(res.status !== 404) console.warn(`${path} non caricato: HTTP ${res.status}`);
      return {};
    }
    const raw = await res.text();
    if(!raw.trim()) return {};
    return JSON.parse(raw);
  }catch(e){
    console.warn(`Errore caricamento ${path}. Il sito userà i dati base.`, e);
    return {};
  }
}

async function loadCmsDataOverrides(){
  const files = [
    '/content/cms/news.json',
    '/content/cms/roster.json',
    '/content/cms/fixtures.json',
    '/content/cms/u21-fixtures.json',
    '/content/cms/gallery-albums.json',
    '/content/cms/sponsors.json',
    '/content/cms/sponsor-packages.json',
    '/content/cms/staff.json',
    '/content/cms/videos.json',
    '/content/cms/club-history.json',
    '/content/cms/events.json'
  ];

  const merged = {};
  const payloads = await Promise.all(files.map(async file => normalizePublishedData(await loadOptionalJson(file))));
  payloads.forEach(clean => {
    Object.keys(clean || {}).forEach(key => {
      merged[key] = clean[key];
    });
  });
  return merged;
}

async function bootData(){
  let dataLoaded = false;
  let loadError = null;

  try{
    const res = await fetch('/content/data.json', {cache:'no-cache'});
    if(!res.ok) throw new Error(`content/data.json non caricato: HTTP ${res.status}`);

    const raw = await res.text();
    const basePublished = normalizePublishedData(JSON.parse(raw));
    const [cmsOverrides, importedNewsIndex, latestSocialFeed] = await Promise.all([
      loadCmsDataOverrides(),
      loadImportedNewsIndex(),
      loadSocialFeed()
    ]);
    const published = normalizePublishedData({...basePublished, ...cmsOverrides});

    // Prima render veloce: usiamo l'indice leggero delle news, non l'archivio completo con bodyHtml.
    // Il testo completo degli articoli viene caricato dopo il primo render o quando l'utente apre le news.
    published.news = mergeCmsNewsWithImportedArchive([...(cmsOverrides.news || []), ...(basePublished.news || [])], importedNewsIndex);
    published.socialFeed = latestSocialFeed.length ? latestSocialFeed : (published.socialFeed || legacySocialToFeed(published.social || []));

    state = applyAutomations(hydrate(published));     // i dati pubblicati hanno priorita' e vengono incrementati dai match terminati
    dataLoaded = true;

    if(current === "news" || current.startsWith("article-")) scheduleImportedNewsArchiveLoad(0);
  }catch(e){
    loadError = e;
    console.error("Errore caricamento content/data.json. Il sito sta usando i defaults interni di app.js.", e);
  }

  render();

  if(!dataLoaded && app){
    app.insertAdjacentHTML("afterbegin", `
      <section class="container" style="padding-top:24px">
        <div class="card card-pad" style="border:2px solid #ef4444">
          <span class="eyebrow">Errore dati CMS</span>
          <h2>content/data.json non è stato caricato correttamente</h2>
          <p class="muted">Il sito sta mostrando i dati di fallback presenti in app.js. Controlla che content/data.json sia JSON valido e pubblicato nella cartella corretta.</p>
          <pre style="white-space:pre-wrap;background:#111;color:#fff;padding:14px;border-radius:12px;overflow:auto">${String(loadError && loadError.message || loadError)}</pre>
        </div>
      </section>
    `);
  }

  showCookie();
}
